style.css:
@-moz-document url-prefix("https://yue3ds.uuscrm.vip/") {
/* Wallpaper */
  html, body {
    background: url("https://i.ibb.co/RG3WxDzn/pink.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Hilangkan warna putih */
  #app,
  .el-container,
  .el-main,
  .el-aside,
  .main,
  .content,
  .friend-list,
  .group-list,
  .chat-container,
  .el-header,
  .el-footer {
    background: transparent !important;
  }

  /* Kotak oranye jadi semi transparan */
  .el-button,
  .btn,
  .add-group,
  .search {
    background: rgba(255, 87, 34, 0.7) !important;
    color: #fff !important;
    border: none !important;
  }

  /* Sidebar kiri */
  .el-aside {
    background: rgba(0,0,0,0.5) !important;
  }

  /* Text lebih jelas */
  .friend-list,
  .group-list,
  .chat-container {
    color: #fff !important;
  }
}
